function view(){if(D.page==='cases')return caseView();if(D.page==='projects')return projectView();if(D.page==='plan')return planView();if(D.page==='chat')return chatView();return typeof extraView==='function'?extraView():'';}
function caseMap(){const nodes=[{kind:'case',id:'c1',title:'会员复购下滑',x:40,y:80,desc:'主目标：'+caseGoal('c1').title},{kind:'case',id:'c2',title:'关键款供给改善',x:40,y:295,desc:'关联经营贡献'},...D.projects.map((p,i)=>({kind:'project',id:p.id,title:p.name,x:390,y:100+i*215,desc:'项目 · 共享资料与工作空间'})),...D.tasks.filter(t=>t.created).map((t,i)=>({kind:'task',id:t.id,title:t.name,x:740,y:40+i*125,desc:taskStatus(t),project:t.project}))];const scale=D.mapScale||Math.min(1,Math.max(.25,(innerWidth-(D.sidebar?248:0)-90)/1010));const edge=(a,b)=>{const x1=a.x+250,y1=a.y+65,x2=b.x,y2=b.y+45;return `<path class="csm-edge" d="M${x1} ${y1}C${x1+65} ${y1} ${x2-65} ${y2} ${x2} ${y2}"/>`;};const edges=nodes.filter(n=>n.kind==='project').map((p,i)=>edge(nodes[i],p)).join('')+nodes.filter(n=>n.kind==='task').map(t=>edge(nodes.find(p=>p.kind==='project'&&p.id===t.project),t)).join('');return `<div class="csm-workspace"><div class="csm-frame"><div class="csm-heading"><strong>事项关联</strong><span>点击节点直接打开 · 拖动空白平移 · 共享项目仅显示一次</span></div><div class="csm-viewport" id="map-viewport" aria-label="Case、项目与分析任务关系图"><div class="csm-canvas" id="map-canvas" style="width:1010px;height:570px;transform:translate(${D.mapPan?.x||0}px,${D.mapPan?.y||0}px) scale(${scale})"><svg class="csm-edges" width="1010" height="570" aria-hidden="true">${edges}</svg>${nodes.map(n=>`<article class="csm-node ${n.kind}" style="left:${n.x}px;top:${n.y}px;width:250px"><button class="csm-node-main" data-action="${n.kind==='case'?'case-detail':n.kind==='project'?'project-detail':'open-task'}" data-id="${n.id}"><span class="csm-node-type">${n.kind==='case'?'Decision Case':n.kind==='project'?'Project':'分析Task'}<span>${n.id.toUpperCase()}</span></span><strong>${H(n.title)}</strong><span class="csm-node-description">${H(n.desc)}</span></button><div class="csm-node-footer"><span>原事项与来源保留</span>${button('打开 ↗',n.kind==='case'?'case-detail':n.kind==='project'?'project-detail':'open-task','',`data-id="${n.id}"`)}</div></article>`).join('')}</div><div class="csm-controls" aria-label="图谱视野">${button('−','map-out','','aria-label="缩小图谱"')}<output>${Math.round(scale*100)}%</output>${button('＋','map-in','','aria-label="放大图谱"')}${button('适应画布','map-fit','')}</div></div><div class="csm-legend"><span>─ 关联项目 / 包含任务</span><span class="continuation">→ 前后续</span><span class="supports">⇢ 支持</span><span>合成关系用于原界面示意，不创建业务记录</span></div></div></div>`;}
function casePage(){if(D.detailCase){const c=D.detailCase,p=D.projects[c==='c1'?0:1],choice=caseChoice(c);return `<section class="case-board">${heading(c==='c1'?'会员复购下滑':'关键款供给改善','Case · 持续推进的业务事项',button('← 返回 Case','case-home','text-button'))}<div class="v020-section v020-new"><div class="v020-row-between"><h2>目标关联 ${badge('本轮增量')}</h2>${button('查看战略与目标','go','text-button','data-page="goals"')}</div><p>主目标：${H(caseGoal(c).title)} / ${H(caseGoal(c).id)} v${caseGoal(c).version}</p><p class="v020-muted">相关目标：经营贡献 · 定量定义引用原SAP。旧Case后补关联保留真实时间，历史不追溯改写。</p></div><nav class="case-detail-tabs" aria-label="Case 详情分区">${[['work','当前工作与决策记录'],['projects','关联项目'],['artifacts','产物'],['history','历史']].map(([id,label])=>button(label,'case-tab','',`data-id="${id}" ${D.caseTab===id?'aria-current="page"':''}`)).join('')}</nav>${D.caseTab==='projects'?section('关联项目',`<p>沿原Case与Project多对多关系，成果只服务本次准确范围。</p>${button(H(p.name),'project-detail','secondary-button',`data-id="${p.id}"`)}`):D.caseTab==='artifacts'?section('关联产物',`<p>会员复购分析 v${D.reportVersion} · 项目${H(p.name)}</p>${button('打开原任务与结果','open-task','secondary-button',`data-id="${D.tasks.find(t=>t.project===p.id&&t.created)?.id||''}"`)}`):D.caseTab==='history'?section('历史',`<p>原判断、目标、方案和人的决定保留当时版本。</p><p>${choice?`已选择方案A v${choice.version}；行动授权与实际反馈另记。`:'尚未记录本轮经营选择。'}</p><p>原目标引用：G-01 v1。${D.goalHistory.length?'新目标已补充，旧引用仍在。':''}</p>`):`<div class="v020-grid">${section('当前工作',`<p>核对适用群体的变化，关键原因尚未确定。</p><p>下一步：确认项目需求、分析重点和综合责任。</p>${button('打开项目需求与任务','project-detail','primary-button',`data-id="${p.id}"`)}`)}${section('判断与决策记录',`<p>候选方案A：先补齐缺货与群体关系证据，再比较试点安排。</p><p>${choice?`人的选择：方案A v${choice.version}`:'人的选择：待明确；未推定行动已获准。'}</p>${button('进入原决策看板','go','secondary-button','data-page="decision"')}`)}</div>`}</section>`;}
return `<section class="case-board"><header class="case-board-heading"><div><p class="eyebrow">持续推进业务事项</p><h1>Decision Case</h1><p>从问题到分析、决策、执行与复盘，让项目围绕一件事持续工作。</p></div>${button('＋ 新建 Case','case-new','primary-button')}</header><div class="case-board-toolbar"><div class="case-board-filters"><input aria-label="搜索 Case、项目或分析任务" placeholder="搜索 Case、项目或分析任务"><select aria-label="Case 状态筛选"><option>全部状态</option><option>进行中</option><option>待反馈</option></select>${button('刷新','refresh','text-button')}</div><div class="case-view-switch" aria-label="Decision Case显示模式">${button('⌁ Case-Star-Map','case-mode','',`data-mode="map" aria-pressed="${D.caseMode==='map'}"`)}${button('常规模式','case-mode','',`data-mode="regular" aria-pressed="${D.caseMode==='regular'}"`)}</div></div>${D.caseMode==='map'?`<div class="v020-row v020-space-top"><label>关系类型 <select aria-label="关系类型"><option>全部关系</option><option>支持</option><option>前后续</option></select></label>${button('补充关系','relations')}</div><p><strong>2</strong> Case　<strong>2</strong> 项目　<strong>${D.tasks.filter(t=>t.created).length}</strong> 分析任务</p>${caseMap()}<details class="v020-space-top"><summary>关系列表与节点导航 · 键盘及窄屏均可使用</summary><p>Case c1 → 会员复购改善 → T1/T3；Case c2 → 商品供给研究 → T4。图谱浏览不启动分析。</p></details>`:`<div class="case-card-grid">${[['c1','会员复购下滑','会员复购改善'],['c2','关键款供给改善','商品供给研究']].map(([id,title,project])=>`<article class="case-card"><div class="case-card-top"><span class="case-status case-status-analyzing">进行中</span>${button('↗','case-detail','icon-button',`data-id="${id}" aria-label="打开Case ${title}"`)}</div><h2>${button(title,'case-detail','',`data-id="${id}"`)}</h2><div><p class="v020-muted">目标：${H(caseGoal(id).title)}</p><p>判断：原因未定，持续核对证据与重要假设。</p></div><p class="v020-muted">关联项目：${project}</p>${button('查看事项','case-detail','text-button',`data-id="${id}"`)}</article>`).join('')}</div>`}<p class="v020-muted v020-space-top">分析任务、人的选择、实际行动与反馈分别记录。原Case与项目关系继续保留。</p></section>`;}
function projectPage(){const p=D.projects.find(x=>x.id===D.detailProject);if(p)return `<section class="case-board">${heading(p.name,'Project · 共享文件，独立任务会话',button('← 返回 Project Map','project-home','text-button'))}<div class="v020-grid">${section('当前工作',`<p>承接人：${H(p.owner)}</p><p>${H(p.scope)}</p><p>下一步：${H(p.next)}</p><div class="v020-row">${button('编辑工作信息','project-work')}${button('重命名','rename-project','text-button',`data-id="${p.id}"`)}</div>`)}${section('关联Case与目标',`<p>${p.id==='p1'?'会员复购下滑 / '+H(D.goal.title):'关键款供给改善 / 经营贡献'}</p>${button('打开Case','case-detail','text-button',`data-id="${p.id==='p1'?'c1':'c2'}"`)}<p class="v020-muted">查询、核对与Studio可无Case。关联按本次确认范围，不猜全部项目Case。</p>`)}</div>${section('项目需求与任务方案 '+badge('本轮增量'),`<p>${D.confirmed?'本次需求v1已确认，正式RAP发布仍独立。':'已有背景直接沿用；本次新工作先轻量明确范围与重点。'}</p><div class="v020-row">${button('查看项目需求方案','plan','primary-button')}${button('查看项目综合','open-task','secondary-button',`data-id="${D.confirmed?.summary||'t3'}"`)}</div>`)}${section('全部分析任务',taskTable(p.id))}<details class="v020-space-top"><summary>项目工作记录与历史</summary><p>项目原身份/文件/原生会话与历史保留。任务归档、恢复不自动执行。</p></details></section>`;
const projects=D.projects.filter(p=>(D.projectFilter==='archived'?p.archived:D.showArchived||!p.archived)&&`${p.name} ${p.owner} ${p.scope}`.toLowerCase().includes((D.projectQuery||'').toLowerCase()));return `<section class="case-board"><header class="case-board-heading"><div><p class="eyebrow">共享文件，独立任务会话</p><h1>Project Map</h1><p>现有项目继续保留原有任务、会话与文件，也可以关联多个Case。</p></div>${button('＋ 新建项目','new-project','primary-button')}</header><div class="case-board-toolbar"><div class="case-board-filters"><input placeholder="搜索项目 / 承接人" aria-label="搜索项目" data-change="project-query" value="${H(D.projectQuery||'')}"><select aria-label="归档状态" data-change="project-filter"><option value="active" ${!D.showArchived?'selected':''}>进行中的项目</option><option value="archived" ${D.projectFilter==='archived'?'selected':''}>已归档项目</option><option value="all" ${D.showArchived?'selected':''}>包括归档项目</option></select>${button('刷新','refresh','text-button')}</div><div class="case-view-switch">${button('▦ 方块','project-mode','',`data-mode="cards" aria-pressed="${D.projectMode==='cards'}"`)}${button('☰ 列表','project-mode','',`data-mode="list" aria-pressed="${D.projectMode==='list'}"`)}</div></div>${D.projectMode==='list'?table(['项目','承接人','工作范围','任务','操作'],projects.map(p=>[H(p.name),H(p.owner),H(p.scope),String(D.tasks.filter(t=>t.created&&t.project===p.id).length),button('项目详情','project-detail','text-button',`data-id="${p.id}"`)])):`<div class="case-card-grid case-project-grid">${projects.map(projectCard).join('')}</div>`}</section>`;}
function taskTable(projectId){return table(['任务','状态','综合责任/依赖','操作'],D.tasks.filter(t=>t.project===projectId&&t.created).map(t=>[H(t.name)+'<br><span class="v020-muted">'+t.id.toUpperCase()+'</span>',taskStatus(t),t.id===(D.confirmed?.summary||'t3')?'项目综合；引用本轮准确子成果':'依项目方案贡献；Agent自主安排协作',`${button('打开任务','open-task','text-button',`data-id="${t.id}"`)} ${button(t.archived?'恢复':'归档',t.archived?'restore-task':'archive-task','text-button',`data-id="${t.id}" ${occupied(t)?'disabled':''}`)}`]));}
function projectCard(p){const tasks=D.tasks.filter(t=>t.created&&t.project===p.id);return `<article class="case-project-card"><div class="case-card-top"><span class="case-project-status">${p.archived?'已归档':'进行中'}</span>${button('↗','project-detail','icon-button',`data-id="${p.id}" aria-label="查看 ${H(p.name)} 项目详情"`)}</div><h2>${button(H(p.name),'project-detail','',`data-id="${p.id}"`)}</h2><p class="case-project-meta">承接人：${H(p.owner)} <span>· 1个Case</span></p><div class="case-project-scope"><span class="case-slot-label">工作范围</span><p class="case-clamp-2">${H(p.scope)}</p></div><div class="case-project-next"><span class="case-slot-label">下一步</span><p class="case-clamp-2">${H(p.next)}</p></div><div class="case-project-task-slot"><div class="case-task-slot-heading"><span>${tasks.length}个任务</span>${button('查看全部任务','project-detail','text-button',`data-id="${p.id}"`)}</div><div class="case-project-tasks">${tasks.slice(0,2).map(t=>button(`<span>${H(t.name)}</span><small>打开任务 ↗</small>`,'open-task','',`data-id="${t.id}"`)).join('')}</div></div><footer><div class="case-project-actions">${button('新建任务','new-task','text-button',`data-id="${p.id}"`)}${button('重命名','rename-project','text-button',`data-id="${p.id}"`)}${button(p.archived?'恢复':'归档',p.archived?'restore-project':'archive-project','text-button',`data-id="${p.id}"`)}</div>${button('编辑工作信息','project-edit','text-button',`data-id="${p.id}"`)}</footer></article>`;}
function planView(){const p=activeProject();const ids=selectedTasks();return `<section class="v020-wrap">${heading(p.name+' / 项目需求方案','项目必经但轻量；Task局部需求继续可选。',button('← 返回项目详情','project-detail','text-button',`data-id="${p.id}"`))}<div class="v020-grid">${section('本次诉求与范围',`<p>核对适用群体复购变化，区分数量贡献与业务解释，比较有依据的改善方向。</p>${check('no-case','本次作为无Case的查询/核对工作',D.plan.noCase,'no-case')}<p class="v020-muted">${D.plan.noCase?'本次不绑定Case，不代办Case选择或行动。':`Case ${projectCase(D.project)} · 主目标 ${H(caseGoal(projectCase(D.project)).title)} / ${H(caseGoal(projectCase(D.project)).id)} v${caseGoal(projectCase(D.project)).version}`}</p><details><summary>资料清单与前置初判</summary><p>交易与群体清单、商品/服务说明、获准访谈摘要。只按清单和基本前提初判，尚未全面读数据、试算或归因。</p><p>首购历史待补；已说明受限范围可开展，独立部分继续。</p></details>`)}${section('项目方法与实际可用能力',`<p>TOC/TP是项目整体约定；具体工具、顺序和其他方法由Agent自主组合。MECE检查本轮结构。</p>${check('skill-analysis','运营数据分析Skill · 已接入；正式新报告契约待候选测评',D.plan.skills.analysis,'skill:analysis')}${check('skill-research','深度研究Skill · 多类事实证据',D.plan.skills.research,'skill:research')}${check('skill-ir','SAP方法 / 会员窗口核对 v3 · 已发布准确版',D.plan.skills.ir,'skill:ir')}<p class="v020-muted">项目既有资料与权限直接继承；连接器配置、范围授权与显式启用分别核对。</p>${button('查看来源与连接配置','settings-connectors','text-button')}`)}</div>${section('问题覆盖与本轮重点',table(['覆盖方面','本轮处理','边界/暂缓理由'],[['群体、人数与购买频次','重点任务T1','数量变化不直接当原因'],['商品、服务与外部证据','重点任务T2','共享证据与交叉影响在综合核对'],['组织长期能力','覆盖，暂不另建Task','按实质发现再建议'],['跨期效果','待观察','窗口未成熟不宣称有效']])+'<p class="v020-muted">分类开放，覆盖和重点分开。问题树子项不自动全部建Task。</p>')}${section('所选Task、依赖与综合责任',`<label class="v020-check">任务方式 <select id="plan-mode" data-change="plan-mode"><option value="multi" ${D.plan.mode==='multi'?'selected':''}>多Task · 维度分析与综合</option><option value="single" ${D.plan.mode==='single'?'selected':''}>单Task · 本任务分析并综合</option></select></label>${D.tasks.filter(t=>t.project===D.project).map(t=>check('select-'+t.id,`${H(t.name)} · ${t.created?'已有Task':'本次待创建'} ${t.archived?'· 已归档':''}`,ids.includes(t.id),'selected:'+t.id,t.archived||D.plan.mode==='single'&&t.id!==ids[0])).join('')}<div class="field"><label for="summary-task">综合责任</label><select id="summary-task" class="v020-input" data-change="summary">${summaryCandidates().filter(t=>D.plan.mode!=='single'||ids.includes(t.id)).map(t=>`<option value="${t.id}" ${t.id===(D.plan.mode==='single'?ids[0]:D.plan.summary)?'selected':''}>${H(t.name)} / ${t.id.toUpperCase()} ${t.created?'（复用已有）':''}</option>`).join('')}</select></div><p class="v020-muted">已有Task可明确承接综合，不强增会话；未选且未创建、归档或其他项目任务不能承接。本轮依赖由Agent在已确认范围内安排，不是Host固定流水线。</p>`)}${section('一次确认，直接承接',`<p>本轮${ids.length}项维度工作，综合由${H(D.tasks.find(t=>t.id===(D.plan.mode==='single'?ids[0]:D.plan.summary))?.name||'待明确')}承接。</p><div class="v020-row">${button('仅确认并创建','confirm-create','secondary-button','id="confirm-create"')}${button('确认并开始','confirm-start','primary-button','id="confirm-start"')}</div><p class="v020-muted">准确需求、所选能力、资料与既有权限直接带入。正式RAP发布独立，不是额外启动门槛；不会修改自动开关或授予经营动作权限。</p>${D.confirmed?`<p>${badge('本次已确认 · 未正式发布')} ${button('打开所选任务','open-task','text-button',`data-id="${D.confirmed.taskIds[0]}"`)}</p>`:''}`)}${section('项目任务',taskTable(D.project)+button('新增任务','new-task','text-button',`data-id="${D.project}"`))}</section>`;}
function chatView(){const p=activeProject(),t=activeTask(),readonly=p.archived||t.archived,summary=D.confirmed?.summary||'t3';return `<div class="chat-page has-messages v020-chat-scroll">${readonly?`<div class="v020-summary v020-section"><strong>已归档，只读</strong><p>原任务、会话和成果保留。${button('恢复原任务','restore-task','secondary-button',`data-id="${t.id}" ${p.archived?'disabled':''}`)}</p></div>`:''}<section class="task-workflow" aria-label="任务工作入口"><div class="task-workflow-heading"><div><p class="eyebrow">${H(p.name)}</p><h1>${H(t.name)}</h1></div><span class="task-workflow-status">${taskStatus(t)}</span></div><nav><ol>${[['资料准备','上传或查看项目文件','open-files'],['需求梳理','可选 · 细化本Task','task-requirement'],['分析对话','按需直接继续','chat-focus'],['结果与审查','查看报告与审查记录','results']].map(([title,desc,a],i)=>`<li>${button(`<span class="task-step-number">${i+1}</span><span><strong>${title}</strong><small>${desc}</small></span>`,a,'')}</li>`).join('')}</ol></nav><p class="task-workflow-help">按需准备资料与需求，也可以直接开始分析。</p></section><div class="v020-summary v020-section v020-new"><div class="v020-row-between"><span>项目需求 ${D.confirmed?'v1已确认':'沿用已有背景，本轮方案待确认'} · 综合责任 ${summary.toUpperCase()}</span>${button('项目需求与综合','plan','text-button')}</div></div><div class="message-scroll"><div class="messages"><article class="message assistant"><div class="message-meta">OptraCall · 合成历史示例</div><div class="message-content"><p>已核窗口内群体变化。尺码缺货仍是候选解释，首购历史尚不足；先保留可成立的阶段判断，再补证比较方案。</p><p class="v020-muted">这条为演示预置历史，不是本页运行模型后的新结果。</p></div></article></div><section class="v020-summary" id="results"><h2 class="v020-compact-title">结果与审查</h2>${section('项目综合 '+badge('本轮增量'),`<p>责任：${H(D.tasks.find(x=>x.id===summary)?.name||t.name)} / ${summary.toUpperCase()}</p><p><strong>阶段结论：</strong>变化描述已有依据，关键约束与原因尚未确定；不预设找到根因或业绩改善。</p><p>准确来源：${H(sourceText())}</p><details><summary>分歧、交叉影响与遗漏</summary><p>商品与服务解释共享群体证据；综合核对口径差异、重复归因与遗漏，不把报告简单拼接。</p></details><div class="v020-report-links">${button('会员复购分析 v'+D.reportVersion+' ↗','report-open','text-button')}${button('查看原综合Task','open-task','text-button',`data-id="${summary}"`)}</div>`)}${section('把这次分析留下来',`<p>任务结束后，提炼方法、流程与判断依据，保存到SAP分析方法；候选与正式发布分开。</p><div class="v020-row">${button('本次分析已结束，提取方法','method-extract','secondary-button')}${button('查看原SAP方法管理','sap-methods','text-button')}</div>${check('local-ir','自动IR提炼 · 全局设置',D.auto.ir,'auto:ir')}<details><summary>整理未完成的材料</summary><p>明确整理已完成部分，保留限制，不冒充完整分析。</p></details>`)}<div class="v020-row">${button('审查结论与建议','review','text-button')}${button('准备增量验证','verification','text-button')}${button('从当前任务建立Case','task-case','text-button')}${button('反馈到资产体系','studio-feedback','text-button')}</div><div class="v020-row v020-space-top">${button('结束本轮并整理','finish','secondary-button')}${button('停止当前任务','stop','secondary-button')}${button('核对原状态并明确继续','resume','secondary-button',t.status!=='stopped'?'disabled':'')}</div><p class="v020-muted">停止不续跑；关闭节点不强杀。保存/自查及所选必要检查不因节点关闭取消。</p></section></div><div class="composer-area"><details class="task-context-options"><summary><strong>本次分析背景</strong>　按需选择</summary><div class="v020-section"><p>继承项目需求 ${D.confirmed?'v1':'已有背景'}；${workCase()?`本次Case ${H(workCase())}，主目标${H(caseGoal(workCase()).title)} v${caseGoal(workCase()).version}`:'本轮无Case，不猜绑定'}</p><p>所选Skill/IR、资料和既有权限按准确确认版本带入；TOC/TP为整体约定，具体步骤自主。</p>${button('查看准确项目方案','plan','text-button')}</div></details><div class="composer"><textarea id="message" ${readonly?'disabled':''} aria-label="消息" placeholder="今天想讨论什么？">${H(t.draft)}</textarea><div class="composer-toolbar">${button('● MiniMax-M3.1-Flash　⌄','model-menu','model-button')}<div class="composer-actions">${button('＋ 文件','open-files','text-button')}${button(t.status==='running'?'停止':'↑',t.status==='running'?'stop':'send','send-button',`${readonly?'disabled':''} aria-label="${t.status==='running'?'停止当前任务':'发送消息'}"`)}</div></div></div><div class="composer-hint"><span>Enter发送 · Shift+Enter换行</span><span>任务和历史已保存在本机（演示）</span></div></div><div class="v020-summary"><details><summary class="v020-muted">Pi能力与命令</summary><p>沿原任务入口和统一Runtime。此原型不执行命令。</p></details></div><footer class="workspace-footer">本机持久项目 · 任务独立对话 · 020_clean 分析与过程 · 060_reports 最终报告 · 请勿上传敏感数据</footer></div>`;}
function sidePanel(){if(D.panel==='review')return `<aside class="conclusion-panel" aria-label="审查结论与建议"><header class="cnr-heading"><div><h2>审查结论与建议</h2><p>针对一版报告，核对重要主张的依据与适用条件。</p></div>${button('收起','close-panel','text-button')}</header><div class="v020-panel-body"><div class="catalog-tabs">${button('结论审查','review-tab',D.reviewTab==='review'?'active':'','data-id="review"')}${button('历史记录','review-tab',D.reviewTab==='history'?'active':'','data-id="history"')}</div>${D.reviewTab==='history'?section('逐稿历史',`<p>v1：已审，${D.reviews[1].carried?'意见已带回':'意见未带回'}。</p><p>v2：${D.reviews[2].reviewed?'已审':'未审'}，${D.reviews[2].carried?'意见已带回':'未带回'}。</p><p>旧稿/原意见保留，不用旧PASS覆盖新稿。</p>`):`<div class="field"><label for="report-version">报告版本</label><select id="report-version" class="v020-input" data-change="report"><option value="1" ${D.reportVersion===1?'selected':''}>会员复购分析 v1</option><option value="2" ${D.reportVersion===2?'selected':''}>会员复购分析 v2</option></select></div><p>${badge(D.reviews[D.reportVersion].reviewed?'本稿已有合成审查':'本稿未审')}</p>${button('查看本稿','report-open','text-button')}<details class="v020-section"><summary>审查依据 · 可选</summary><p>本次准确来源：${H(sourceText())}；项目需求v1。未核项和读取范围如实保留。</p></details><div class="v020-row">${button('开始审查','review-report','primary-button')}${button('停止','review-stop','secondary-button')}</div>${D.reviews[D.reportVersion].reviewed?`<section class="v020-section"><h3>本稿意见</h3><p>首购历史不足，应限制完整复购率与因果结论；核查成本、资金与群体适配条件。</p>${button(D.reviews[D.reportVersion].carried?'本稿意见已带回原Agent':'带回原Agent核实','carry-review','secondary-button')}</section>`:`<p class="v020-muted">本稿暂无审查意见，不能挪用另一稿意见。</p>${button('本稿暂无意见可带回','carry-review','secondary-button','disabled')}`}<div class="v020-row v020-space-top">${button('原Agent修订另存 v2','new-report','secondary-button')}${button('打开原决策工作区','go','text-button','data-page="decision"')}</div>${check('local-review','自动审查与修订 · 全局设置',D.auto.review,'auto:review')}`}</div></aside>`;
if(!D.files||D.panel!=='files')return '';return `<aside id="project-files" class="project-files" aria-label="项目文件"><header class="project-files-heading"><div><p class="eyebrow">项目空间</p><h2>项目文件</h2></div>${button('×','close-panel','icon-button','aria-label="关闭项目文件栏"')}</header><div class="v020-panel-body"><p>${icon('folder')} ${H(activeProject().name)}</p><p class="v020-muted">本机项目 · 3个共享文件夹</p>${section('数据库',`<p>任务继承项目来源，配置、范围授权和模型出口分别核对。</p>${button('共享连接','settings-connectors','text-button')} ${button('引用连接并授权','connect-authorize','secondary-button')}`)}${section('查询结果与来源',`<p>沿原来源、权限和准确版本；不因推荐或导航变化扩大授权。</p>${button('数据说明 / 来源','sources','text-button')} ${button('前往Studio','go','text-button','data-page="studio"')}`)}<label for="upload-place">上传位置</label><select id="upload-place" class="v020-input"><option>010_draw · 原件归档</option><option>020_clean · 分析资料</option></select>${button('上传文件','demo-upload','secondary-button v020-space-top')}<p class="v020-muted">Demo不读取或上传本机文件。</p><details><summary>010_draw · 原件归档</summary><p class="v020-muted">本例原件不在此展示。</p></details><details open><summary>020_clean · 分析与过程</summary><p>会员交易清单.csv</p><p>访谈与商品说明.md</p></details><details open><summary>060_reports · 最终报告</summary><p>${button('会员复购分析-v1.md','report-v1','text-button')}</p>${D.reportVersion===2?button('会员复购分析-v2.md','report-v2','text-button'):''}<div class="v020-row">${button('生成PPTX','ppt-generate','text-button')}${button('逐页精修','ppt-refiner','text-button')}</div></details>${check('local-save','自动报告保存 · 全局设置',D.auto.save,'auto:save')}</div></aside>`;}
function coreAction(action,el){if((activeTask().archived||activeProject().archived)&&['send','task-requirement'].includes(action)){notify('当前任务或项目已归档，只读。请先恢复原记录。');return true;}switch(action){case'close-dialog':case'report-close':return true;case'open-files':D.files=true;D.panel='files';break;case'map-in':D.mapScale=Math.min(1.5,(D.mapScale||1)+.1);break;case'map-out':D.mapScale=Math.max(.25,(D.mapScale||1)-.1);break;case'map-fit':D.mapScale=null;D.mapPan={x:0,y:0};break;case'case-tab':D.caseTab=el.dataset.id;break;case'refresh':D.notice='已只读刷新本页合成状态；没有请求产品服务。';break;case'project-edit':selectProject(el.dataset.id||D.project);case'project-work':return showForm('编辑工作信息','下一步',v=>{activeProject().next=v;render();},activeProject().next);case'chat-focus':document.getElementById('message')?.focus();return true;case'results':document.getElementById('results')?.scrollIntoView({behavior:'instant'});return true;case'review-tab':D.reviewTab=el.dataset.id;break;case'review-stop':D.notice='停止本次审查，不启动后续修订或收尾动作。';break;case'report-v1':D.reportVersion=1;return coreAction('report-open',el);case'report-v2':D.reportVersion=2;return coreAction('report-open',el);case'report-open':return showReport();case'send':if(!D.confirmed){D.page='plan';D.notice='本轮新工作先在原项目方案集中确认，不逐Task重发。';}else{activeTask().status='running';D.notice='仅载入本任务运行界面；未发送模型请求。';}break;case'task-requirement':return showForm('Task局部需求（可选）','补充本任务说明',v=>{activeTask().draft=v;D.notice='局部草稿保留；共同目标/口径/核心方法变化回项目集中处理。';render();});case'task-case':D.page='cases';D.detailCase=workCase()||null;D.notice=workCase()?'打开本次准确Case。':'本次无Case；需要持续经营问题时准备关联，不猜其他Case。';break;default:return false;}render();return true;}
function showReport(){const d=document.createElement('dialog');d.className='v020-dialog';d.innerHTML=`<h2>会员复购分析 v${D.reportVersion} · 合成报告</h2><p>${badge(D.reviews[D.reportVersion].reviewed?'本稿已审（预置回执）':'本稿未审')}</p><p>已核窗口内购买群体变化；缺货仍是候选解释。首购历史不足，尚不能断言完整首购复购率或找到根因。</p><h3>准确来源</h3><p>${H(sourceText())}；项目需求v1。</p><h3>方法与限制</h3><p>项目TOC/TP约定、所选运营Skill/已发布IR用于本次判断；具体方法与原脚本检查由Agent自主安排。新版Skill契约仍需正式候选及独立测评，原型不冒称已经生效。</p><h3>阶段交付</h3><p>先交有依据部分，补足观察与供给资料后继续核对。专业正确、用户选择、经营动作与效果分别核定。</p>${button('关闭报告','report-close','secondary-button')}`;document.querySelector('.app').append(d);d.querySelector('button').onclick=()=>{d.close();d.remove();};d.showModal();}
const originalAct=act;act=function(action,el){if(coreAction(action,el||{dataset:{}})!==false)return;return originalAct(action,el);};window.demo.act=act;

let mapDrag=null;document.addEventListener("pointerdown",e=>{if(e.target.closest("#map-viewport")&&!e.target.closest("button")){mapDrag={x:e.clientX,y:e.clientY,px:D.mapPan?.x||0,py:D.mapPan?.y||0};}});document.addEventListener("pointermove",e=>{if(!mapDrag)return;D.mapPan={x:mapDrag.px+e.clientX-mapDrag.x,y:mapDrag.py+e.clientY-mapDrag.y};const c=document.getElementById("map-canvas");if(c)c.style.transform=`translate(${D.mapPan.x}px,${D.mapPan.y}px) scale(${D.mapScale||Math.min(1,Math.max(.25,(innerWidth-(D.sidebar?248:0)-90)/1010))})`;});document.addEventListener("pointerup",()=>mapDrag=null);

function originalDetailDialog(title,subtitle,body,kind,close){return `<dialog id="v020-original-detail" class="case-dialog ${kind}" tabindex="-1" aria-labelledby="v020-detail-title"><header class="case-dialog-heading"><div><h2 id="v020-detail-title">${H(title)}</h2><p>${H(subtitle)}</p></div>${button('✕',close,'icon-button',`aria-label="关闭${H(title)}"`)}</header>${body}</dialog>`;}
function caseView(){if(!D.detailCase)return casePage();const id=D.detailCase,detail=casePage();D.detailCase=null;const background=casePage();D.detailCase=id;const body=detail.replace(/^<section[^>]*>[\s\S]*?<\/header>/,'').replace(/<\/section>$/,'');return background+originalDetailDialog(id==='c1'?'会员复购下滑':'关键款供给改善','进行中 · 原事项与历史保留',`<div class="case-detail-actions">${button('更新状态','case-status','secondary-button')}${button('编辑 Case','case-edit','secondary-button')}${button('追加说明','case-note','secondary-button')}${button('刷新详情','refresh','text-button')}</div>`+body,'case-detail-dialog','case-home');}
function projectView(){if(!D.detailProject)return projectPage();const id=D.detailProject,p=activeProject();D.detailProject=null;const background=projectPage();D.detailProject=id;const tasks=D.tasks.filter(t=>t.project===p.id&&t.created),summary=D.confirmed?.summary||tasks.find(t=>t.id==='t3')?.id||tasks[0]?.id;return background+originalDetailDialog(p.name,`${tasks.length}个任务 · ${p.id==='p1'||p.id==='p2'?'1个Case':'未关联Case'}${p.archived?' · 已归档，只读':''}`,`<div class="case-section-heading"><div><h3>项目全局工作信息</h3><p>此处与全部关联Case共用同一份信息。</p></div>${button('编辑工作信息','project-work','secondary-button',p.archived?'disabled':'')}</div><dl class="case-project-work"><div><dt>工作状态</dt><dd>${p.archived?'已归档':'进行中'} · 承接人：${H(p.owner)}</dd></div><div><dt>工作范围</dt><dd>${H(p.scope)}</dd></div><div><dt>下一步</dt><dd>${H(p.next)}</dd></div></dl><div class="case-project-case-links"><h3>关联Case</h3><p>${p.id==='p1'?'会员复购下滑':p.id==='p2'?'关键款供给改善':'此项目尚未关联Case，可以独立工作。'}</p></div>${section('项目需求与任务方案 '+badge('本轮增量'),`<p>${D.confirmed?'本次需求v1已确认，正式RAP发布仍独立。':'已有背景沿用；本次新工作先轻量明确范围与重点。'}</p><div class="v020-row">${button('查看项目需求方案','plan','primary-button',p.archived?'disabled':'')}${summary?button('查看项目综合','open-task','secondary-button',`data-id="${summary}"`):''}</div>`)}<div class="case-section-heading"><h3>全部任务</h3>${button('＋ 新建任务','new-task','secondary-button',`data-id="${p.id}" ${p.archived?'disabled':''}`)}</div><div class="case-project-tasks">${tasks.map(t=>button(`<span>${H(t.name)}</span><small>${taskStatus(t)} ↗</small>`,'open-task','',`data-id="${t.id}"`)).join('')}</div><div class="case-section-heading case-history-section"><div><h3>项目工作记录</h3><p>全局记录保留反馈来源与业务信息变更。</p></div>${button('追加说明','project-note','text-button')}</div><p class="case-help">原项目身份、文件、原生会话与历史保留。合成记录不请求本机服务。</p><div class="case-detail-footer"><span>本页合成资料</span><div class="case-project-actions">${button('重命名','rename-project','text-button',`data-id="${p.id}"`)}${button(p.archived?'恢复项目':'归档',p.archived?'restore-project':'archive-project','text-button',`data-id="${p.id}"`)}</div></div>`,'case-project-detail-dialog','project-home');}
